style.css:
@-moz-document url-prefix("http") {
/* 1. Stop standard browser carets (Chrome, Firefox, Safari) */
  * {
      caret-color: inherit !important;
  }
  
  /* 2. Target Monaco/VS Code-based editors (Codesandbox, GitHub, etc.) */
  .monaco-editor .cursors-layer .cursor {
      animation: none !important;
      transition: none !important;
      visibility: visible !important;
      opacity: 1 !important;
  }
  
  /* 3. Target Ace Editor and other common web IDEs */
  .ace_cursor, 
  .CodeMirror-cursor, 
  .cm-cursor {
      animation: none !important;
      visibility: visible !important;
      display: block !important;
      opacity: 1 !important;
  }
  
  /* 4. Target specialty editors */
  .kix-cursor-caret {
      display: block !important;
      visibility: visible !important;
      animation: none !important;
  }
  
  /*5. Target Google docs*/
  .kix-cursor.docs-ui-unprintable.docs-text-ui-cursor-blink {
      animation-name: none !important;
  }
  
  /* 6. Target Notion and Block-based Editors */
  .notion-cursor-default, 
  [data-relaxed-cursor="true"] {
      animation: none !important;
      opacity: 1 !important;
      visibility: visible !important;
  }
  
  /* 7. Target Xterm.js (Web Terminals like Vercel, Replit, Azure Shell) */
  .xterm-cursor-layer .xterm-cursor {
      animation: none !important;
      display: block !important;
  }
  
  /* 8. Target ProseMirror and TipTap (Common in modern CMS/Rich Text) */
  .ProseMirror .ProseMirror-cursor {
      border-left: 2px solid currentColor;
      animation: none !important;
      visibility: visible !important;
  }
  
  /* 9. Target Draft.js (Used by Facebook, Messenger, and older React apps) */
  .public-DraftEditorPlaceholder-root, 
  .public-DraftEditor-content {
      caret-color: currentColor !important;
  }
  
  /* 10. Heavy-duty "Nuclear" option for custom SVG/Canvas carets */
  [class*="cursor"], [class*="caret"], [id*="cursor"], [id*="caret"] {
      animation-iteration-count: 0 !important;
      animation-name: none !important;
      animation-duration: 0s !important;
      transition: none !important;
  }
  
  /* 11. Target CodeMirror 6 / EditorView (The ͼ1 specific styles) */
  .ͼ1.cm-focused > .cm-scroller > .cm-cursorLayer {
      animation: none !important;
  }
  .ͼ1.cm-focused > .cm-scroller > .cm-cursorLayer .cm-cursor {
      display: block !important;
      opacity: 1 !important;
      visibility: visible !important;
  }
  
  /* 12. Target Google Search AI "Generating" Caret */
  .CEpIFc[animating-caret],
  .CEpIFc::after {
      animation: none !important;
      border-right: 2px solid currentColor !important; 
      visibility: visible !important;
      opacity: 0 !important;
      display: inline-block !important;
  }
  [animating-caret] {
      animation-name: none !important;
      animation-duration: 0s !important;
  }
}
